(function($){window.openFusionElement=function(selector){const element=$(selector);const overlay=$("#overlay-"+element.attr("id"));element.addClass("opening");overlay.addClass("active");setTimeout(function(){element.removeClass("opening").addClass("active");element.trigger("fusionOpened")},300);element.find(".close-btn").on("click",function(){closeFusionElement(selector)});overlay.on("click",function(){closeFusionElement(selector)})};window.closeFusionElement=function(selector){const element=$(selector);const overlay=$("#overlay-"+element.attr("id"));element.removeClass("active").addClass("closing");overlay.removeClass("active");setTimeout(function(){element.removeClass("closing");element.trigger("fusionClosed")},300)};window.fusionSwapElement=function(selector){let element=$(selector);let linkTitle=element.find(".swap-title");let swapContent=element.find(".swap-box");if(swapContent.is(":visible")){swapContent.hide();linkTitle.show();element.trigger("fusionHideSwap")}else{swapContent.show();linkTitle.hide();element.trigger("fusionShowSwap")}};$.fn.fusionObjects=function(){$("body").on("click","[data-pf-toggle]",function(){const toggleType=$(this).data("pf-toggle");const toggleId=$(this).data("toggle-id");const elementSelector="#"+toggleId;if(toggleType==="canvas"){openFusionElement(elementSelector)}else if(toggleType==="dropdown"){$(elementSelector).toggleClass("active")}else if(toggleType=="swap"){fusionSwapElement(elementSelector)}return false});return this};$("[data-pf-toggle]").fusionObjects()})(jQuery);